tool_input.command:
tail -n +2 data/prediction_log.csv | awk -F '[T,]' '{day=$1; pred=$3; print day "," pred}' | sort | awk -F ',' '{
    sum[$1] += $2;
    sum_sq[$1] += $2 * $2;
    count[$1]++;
}
END {
    for (day in sum) {
        mean = sum[day] / count[day];
        variance = (sum_sq[day] / count[day]) - (mean * mean);
        std = sqrt(variance);
        print day "," mean "," std;
    }
}' | sort > submission/daily_stats.csv

awk -F ',' '{
    days[NR] = $1;
    means[NR] = $2;
    stds[NR] = $3;
}
END {
    for (i = 1; i <= NR; i++) {
        window_start = (i - 1 > 0) ? i - 1 : 1;
        window_end = (i + 1 <= NR) ? i + 1 : NR;
        rolling_mean = 0;
        for (j = window_start; j <= window_end; j++) {
            rolling_mean += means[j];
        }
        rolling_mean /= (window_end - window_start + 1);
        print days[i] "," means[i] "," stds[i] "," rolling_mean;
    }
}' submission/daily_stats.csv | awk -F ',' '{
    if (NR > 1) {
        prev_rolling = last_rolling;
        curr_rolling = $4;
        if (prev_rolling != "" && (curr_rolling - prev_rolling) > 0.5) {
            print $1;
            exit;
        }
    }
    last_rolling = $4;
}' > submission/shift_onset.txt

if [ -s submission/shift_onset.txt ]; then
    onset=$(cat submission/shift_onset.txt);
else
    onset="1970-01-01";
fi;
echo "{\"onset\": \"$onset\"}" > submission/answers.json
